#!/usr/bin/env python3
"""Corpus M2b: can the falsifying class be generated by mutating the PoV?

Two arms, run in order, so the second only happens if the first fails:

  naive  — flip random bytes. Predicted to yield ~0 inputs that reach the
           changed line, because a mutated PNG chunk fails its CRC and libpng
           rejects it before the keyword parse.
  crc    — flip random bytes, then recompute the chunk CRCs. Repairing a CRC is
           derivable from the PNG spec, which is a permitted input, so this is
           inside the leakage rules. Knowing WHICH chunk to target would not be,
           so the mutator is told nothing about iCCP.

Seeded, so a class is reproducible from its seed rather than only from its
outputs.

Usage: mutate-class.py <seed.png> <outdir> <reader-probe> <marker> [n] [rngseed]
"""
import os
import random
import struct
import subprocess
import sys
import zlib

SIG = b'\x89PNG\r\n\x1a\n'


def chunks(b):
    """Walk PNG chunks. Returns [(type, data, declared_crc, offset)]."""
    out, i = [], len(SIG)
    while i + 8 <= len(b):
        ln = struct.unpack('>I', b[i:i + 4])[0]
        typ = b[i + 4:i + 8]
        data = b[i + 8:i + 8 + ln]
        if i + 8 + ln + 4 > len(b):
            break
        crc = struct.unpack('>I', b[i + 8 + ln:i + 12 + ln])[0]
        out.append((typ, data, crc, i))
        i += 12 + ln
        if typ == b'IEND':
            break
    return out


def rebuild(cs):
    """Reassemble a PNG from chunks, recomputing every CRC."""
    b = bytearray(SIG)
    for typ, data, _crc, _off in cs:
        b += struct.pack('>I', len(data)) + typ + data
        b += struct.pack('>I', zlib.crc32(typ + data) & 0xFFFFFFFF)
    return bytes(b)


def naive(seed_bytes, rng, k=8):
    """Flip k random bytes anywhere after the signature. CRCs left broken."""
    b = bytearray(seed_bytes)
    for _ in range(k):
        i = rng.randrange(len(SIG), len(b))
        b[i] = rng.randrange(256)
    return bytes(b)


def crc_repaired(seed_bytes, rng, k=8):
    """Flip k random bytes inside chunk DATA, then recompute every CRC.

    The mutator is not told which chunk matters: it picks uniformly among all
    of them, so reaching the changed line has to come from the seed's structure
    rather than from insight about iCCP.
    """
    cs = [list(c) for c in chunks(seed_bytes)]
    mutable = [j for j, c in enumerate(cs) if len(c[1]) > 0 and c[0] != b'IEND']
    if not mutable:
        return rebuild([tuple(c) for c in cs])
    for _ in range(k):
        j = rng.choice(mutable)
        data = bytearray(cs[j][1])
        i = rng.randrange(len(data))
        data[i] = rng.randrange(256)
        cs[j][1] = bytes(data)
    return rebuild([tuple(c) for c in cs])


def reaches(reader, path, marker):
    try:
        # No check=: the reader exits non-zero when the sanitizer fires, and
        # that is a result. The marker in the output is the observation.
        p = subprocess.run([reader, path], capture_output=True, timeout=10)  # noqa: PLW1510
    except subprocess.TimeoutExpired:
        return False
    return marker.encode() in p.stdout + p.stderr


def main():
    seed_path, outdir, reader, marker = sys.argv[1:5]
    n = int(sys.argv[5]) if len(sys.argv) > 5 else 500
    rngseed = int(sys.argv[6]) if len(sys.argv) > 6 else 1
    seed_bytes = open(seed_path, 'rb').read()

    os.makedirs(outdir, exist_ok=True)
    results = {}
    for arm, fn in (('naive', naive), ('crc', crc_repaired)):
        # Per-arm control, and it has to be per-arm rather than once.
        #
        # build-probe.sh self-tests the PROBE on the seed, so a probe that never
        # linked yields 0 and is caught. That covers an arm whose count comes
        # back zero. It does not cover an arm whose TRANSFORM is broken: the crc
        # arm parses the PNG into chunks and reassembles it, and if that
        # round-trip were subtly wrong every mutant would be malformed and the
        # arm would report a plausible-looking low non-zero. 51 of 500 does not
        # announce itself as broken the way 0 of 500 does.
        #
        # So each arm transforms the seed with zero mutations and must still
        # reach the line. That is an internal control on the transform, separate
        # from any claim about inputs.
        ctrl = os.path.join(outdir, f'.control-{arm}.png')
        with open(ctrl, 'wb') as f:
            f.write(fn(seed_bytes, random.Random(0), k=0))
        if not reaches(reader, ctrl, marker):
            print(f'{arm}: TRANSFORM BROKEN — the unmutated seed does not reach '
                  f'the changed line through this arm', file=sys.stderr)
            return 1

        rng = random.Random(rngseed)
        d = os.path.join(outdir, arm)
        os.makedirs(d, exist_ok=True)
        hit = 0
        distinct = set()
        for i in range(n):
            m = fn(seed_bytes, rng)
            p = os.path.join(d, f'{i:05d}.png')
            with open(p, 'wb') as f:
                f.write(m)
            if reaches(reader, p, marker):
                hit += 1
                distinct.add(m)
            else:
                os.remove(p)
        # The seed itself is excluded: a class whose only member is the seed is
        # the degenerate result this experiment exists to detect.
        non_seed = len([m for m in distinct if m != seed_bytes])
        results[arm] = (hit, len(distinct), non_seed)
        print(f'{arm:6} {hit:5}/{n} reached the changed line, '
              f'{len(distinct)} distinct, {non_seed} of them not the seed', flush=True)
    return 0


if __name__ == '__main__':
    sys.exit(main())
